/// Reject publicly compromised CA keys even when reissued or cross-signed.
/// Policy mirrors Node/Bun's October 2026 eMudhra mitigation, not CA names.
pub fn rejectCompromisedSpki(p: Parsed) error{CertificateRevoked}!void {
    var digest: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(p.slice(p.pub_key_info_slice), &digest, .{});
    const blocked = [_][]const u8{
        "49dd353dc2b919a3770645117d0e60c16115e7d1bc259eefe734b00ea434fe5f",
        "5c0660a2b164910d8ff589c18e14552e9e0ec237dcefe2cb736d41a4811f81a0",
        "63ecefee431d49523bc1136c4e72d0206a477086caf606cd5cf025686c109cf8",
