pub fn verify(parsed_subject: Parsed, parsed_issuer: Parsed, now_sec: i64) VerifyError!void {
    try parsed_subject.rejectCompromisedSpki();
    try parsed_issuer.rejectCompromisedSpki();

// Inspect the entire presented chain before normal verification can
// terminate early at a locally trusted intermediate.
var policy_decoder = certs;
while (!policy_decoder.eof()) {
    try policy_decoder.ensure(3);
    const policy_size = policy_decoder.decode(u24);
    const policy_cert = try policy_decoder.sub(policy_size);
    const parsed = try (Certificate{
        .buffer = policy_cert.buf,
        .index = @intCast(policy_cert.idx),
    }).parse();
    try parsed.rejectCompromisedSpki();
    if (tls_version == .tls_1_3) {
        try policy_decoder.ensure(2);
        const policy_ext_size = policy_decoder.decode(u16);
        _ = try policy_decoder.sub(policy_ext_size);
    }
}

var certs_decoder = certs;

// Prefix layouts from wincrypt.h. Windows may obtain issuers through AIA;
// checking only the peer-supplied chain would miss those certificates.
const ChainContextPrefix = extern struct {
    cbSize: u32,
    trust_status: [2]u32,
    count: u32,
    chains: [*]const *const SimpleChainPrefix,
};
const SimpleChainPrefix = extern struct {
    cbSize: u32,
    trust_status: [2]u32,
    count: u32,
    elements: [*]const *const ChainElementPrefix,
};
const ChainElementPrefix = extern struct {
    cbSize: u32,
    certificate: *const crypt32.CERT_CONTEXT,
};

fn rejectCompromisedChain(context: *const crypt32.CERT_CHAIN.CONTEXT) VerifyError!void {
    const built: *const ChainContextPrefix = @ptrCast(@alignCast(context));
    for (built.chains[0..built.count]) |simple| {
        for (simple.elements[0..simple.count]) |element| {
            const cert = element.certificate;
            const parsed = (std.crypto.Certificate{
                .buffer = cert.pbCertEncoded[0..cert.cbCertEncoded],
                .index = 0,
            }).parse() catch return error.TlsCertificateNotVerified;
            try parsed.rejectCompromisedSpki();
        }
    }
}

